import '../../src/ui/index.css';
import { Scene, PerspectiveCamera, Color, SRGBColorSpace, Vector2 } from 'three';
import * as kit from '../../src/kit/three/index.js';
const canvas=document.querySelector('canvas');
const renderer=kit.createRenderer(canvas);
const scene=new Scene();scene.background=new Color(getComputedStyle(document.body).backgroundColor);
const camera=new PerspectiveCamera(45,1,0.1,100);camera.position.set(0,0,4);
const controls=kit.createOrbit(camera,canvas,{minDistance:2,maxDistance:10});
const environment=kit.roomEnvironment(renderer,scene);
const positions=new Float32Array([0,1,0,-1,-1,0,1,-1,0]);
const base64=btoa(String.fromCharCode(...new Uint8Array(positions.buffer)));
const json={asset:{version:'2.0'},scene:0,scenes:[{nodes:[0]}],nodes:[{mesh:0}],meshes:[{primitives:[{attributes:{POSITION:0},material:0}]}],materials:[{pbrMetallicRoughness:{baseColorFactor:[0.7,0.7,0.75,1],metallicFactor:0.2,roughnessFactor:0.3}}],buffers:[{byteLength:positions.byteLength,uri:`data:application/octet-stream;base64,${base64}`}],bufferViews:[{buffer:0,byteLength:positions.byteLength}],accessors:[{bufferView:0,componentType:5126,count:3,type:'VEC3',min:[-1,-1,0],max:[1,1,0]}]};
const model=await kit.loadGLTF(`data:model/gltf+json,${encodeURIComponent(JSON.stringify(json))}`);scene.add(model.scene);
const composer=kit.createComposer(renderer,scene,camera,{bloom:{strength:0.1}});
const stopResize=kit.observeSize(renderer,camera,{onResize:({width,height,pixelRatio})=>{composer.setPixelRatio(pixelRatio);composer.setSize(width,height)}});
const state={frames:0,lost:0,restored:0,color:renderer.outputColorSpace===SRGBColorSpace};
const loop=kit.createLoop(renderer,(delta)=>{controls.update(delta);composer.render();state.frames++});
const stopGuard=kit.guardContext(canvas,{onLost:()=>{state.lost++;loop.setPaused(true)},onRestored:()=>{state.restored++;loop.setPaused(false)}});
const contextExtension=renderer.getContext().getExtension('WEBGL_lose_context');
window.kit={state,renderer,camera,controls,size:()=>renderer.getSize(new Vector2()).toArray(),lose:()=>contextExtension.loseContext(),restore:()=>contextExtension.restoreContext(),dispose:()=>{loop.dispose();stopResize();stopGuard();controls.dispose();environment.dispose();kit.disposeObject(scene);for(const pass of composer.passes)pass.dispose?.();composer.dispose();renderer.dispose();kit.disposeLoaders()}};
loop.start();document.body.classList.add('ready');
